import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Users, 
  FolderKanban, 
  Settings, 
  LogOut,
  Bell,
  Search,
  Menu,
  X,
  TrendingUp,
  DollarSign,
  Calendar,
  CheckCircle,
  Clock,
  ArrowUpRight,
  ArrowDownRight,
  MoreHorizontal,
  Plus
} from 'lucide-react';
import munLogo from '../assets/images/MUN.png';

const Dashboard = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const navigate = useNavigate();

  const handleLogout = () => {
    navigate('/login');
  };

  const stats = [
    { 
      title: 'Total Projects', 
      value: '24', 
      change: '+12%', 
      trend: 'up',
      icon: FolderKanban,
      color: 'blue'
    },
    { 
      title: 'Active Clients', 
      value: '18', 
      change: '+8%', 
      trend: 'up',
      icon: Users,
      color: 'green'
    },
    { 
      title: 'Revenue', 
      value: '$48.5K', 
      change: '+24%', 
      trend: 'up',
      icon: DollarSign,
      color: 'purple'
    },
    { 
      title: 'Pending Tasks', 
      value: '7', 
      change: '-3', 
      trend: 'down',
      icon: Clock,
      color: 'orange'
    }
  ];

  const recentProjects = [
    { name: 'E-Commerce Platform', client: 'TechStore Inc.', status: 'In Progress', progress: 75, deadline: 'Dec 15' },
    { name: 'Portfolio Website', client: 'Design Studio', status: 'Completed', progress: 100, deadline: 'Dec 10' },
    { name: 'Mobile App UI', client: 'StartUp Hub', status: 'In Review', progress: 90, deadline: 'Dec 20' },
    { name: 'Admin Dashboard', client: 'Enterprise Co.', status: 'In Progress', progress: 60, deadline: 'Dec 25' }
  ];

  const recentActivity = [
    { action: 'Project completed', project: 'Portfolio Website', time: '2 hours ago', icon: CheckCircle },
    { action: 'New client added', project: 'TechStore Inc.', time: '5 hours ago', icon: Users },
    { action: 'Task updated', project: 'E-Commerce Platform', time: '1 day ago', icon: Clock },
    { action: 'Payment received', project: 'Design Studio', time: '2 days ago', icon: DollarSign }
  ];

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, path: '/dashboard' },
    { id: 'projects', label: 'Projects', icon: FolderKanban, path: '/projects' },
    { id: 'clients', label: 'Clients', icon: Users, path: '/clients' },
    { id: 'settings', label: 'Settings', icon: Settings, path: '/settings' }
  ];

  return (
    <div className="min-h-screen bg-[#0a1628] flex">
      {/* Sidebar */}
      <aside 
        className={`fixed lg:relative inset-y-0 left-0 z-40 w-72 bg-[#0f172a] border-r border-white/5 transform transition-transform duration-300 lg:transform-none flex-shrink-0 ${
          sidebarOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {/* Logo */}
        <div className="p-6 border-b border-white/5">
          <Link to="/" className="flex items-center gap-3 group">
            <div className="w-12 h-12 rounded-full overflow-hidden bg-blue-600 flex items-center justify-center ring-2 ring-blue-500/30 group-hover:ring-blue-500/50 transition-all">
              <img src={munLogo} alt="MUN Logo" className="w-12 h-12 object-cover" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-white">Project MUN</h1>
              <p className="text-xs text-gray-400">Admin Dashboard</p>
            </div>
          </Link>
        </div>

        {/* User Profile */}
        <div className="px-4 py-4">
          <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5 border border-white/5">
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-blue-600 flex items-center justify-center text-white font-semibold">
              RA
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-white truncate">Ruben Albao</p>
              <p className="text-xs text-gray-400 truncate">Frontend Developer</p>
            </div>
            <div className="w-2 h-2 bg-green-500 rounded-full"></div>
          </div>
        </div>

        {/* Navigation */}
        <div className="px-4 mb-2">
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Menu</p>
        </div>
        <nav className="px-4 space-y-1">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <Link
                key={item.id}
                to={item.path}
                onClick={() => setActiveTab(item.id)}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all group ${
                  isActive 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/25' 
                    : 'text-gray-400 hover:text-white hover:bg-white/5'
                }`}
              >
                <div className={`p-2 rounded-lg transition-colors ${
                  isActive ? 'bg-white/20' : 'bg-white/5 group-hover:bg-white/10'
                }`}>
                  <Icon className="w-4 h-4" />
                </div>
                {item.label}
                {isActive && (
                  <div className="ml-auto w-1.5 h-1.5 rounded-full bg-white"></div>
                )}
              </Link>
            );
          })}
        </nav>

        {/* Quick Actions */}
        <div className="px-4 mt-6 mb-2">
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Quick Actions</p>
        </div>
        <div className="px-4 space-y-1">
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium text-gray-400 hover:text-white hover:bg-white/5 transition-all group">
            <div className="p-2 rounded-lg bg-white/5 group-hover:bg-white/10 transition-colors">
              <Plus className="w-4 h-4" />
            </div>
            New Project
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium text-gray-400 hover:text-white hover:bg-white/5 transition-all group">
            <div className="p-2 rounded-lg bg-white/5 group-hover:bg-white/10 transition-colors">
              <Users className="w-4 h-4" />
            </div>
            Add Client
          </button>
        </div>

        {/* Logout */}
        <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-white/5 bg-[#0f172a]">
          <button
            onClick={handleLogout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium text-red-400 hover:bg-red-500/10 transition-all group"
          >
            <div className="p-2 rounded-lg bg-red-500/10 group-hover:bg-red-500/20 transition-colors">
              <LogOut className="w-4 h-4" />
            </div>
            Logout
          </button>
        </div>
      </aside>

      {/* Overlay for mobile */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        ></div>
      )}

      {/* Main Content */}
      <main className="flex-1 min-w-0">
        {/* Header */}
        <header className="sticky top-0 z-20 bg-[#0a1628]/80 backdrop-blur-md border-b border-white/5 px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <button
                onClick={() => setSidebarOpen(true)}
                className="lg:hidden p-2 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
              >
                <Menu className="w-6 h-6" />
              </button>
              <h2 className="text-xl font-semibold text-white capitalize">{activeTab}</h2>
            </div>

            <div className="flex items-center gap-4">
              {/* Search */}
              <div className="hidden md:flex items-center relative">
                <Search className="absolute left-3 w-4 h-4 text-gray-500" />
                <input
                  type="text"
                  placeholder="Search..."
                  className="pl-10 pr-4 py-2 rounded-xl bg-white/5 border border-white/10 text-white text-sm placeholder-gray-500 focus:outline-none focus:border-blue-500 w-64"
                />
              </div>

              {/* Notifications */}
              <button className="relative p-2 rounded-xl bg-white/5 text-gray-400 hover:text-white hover:bg-white/10 transition-colors">
                <Bell className="w-5 h-5" />
                <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full"></span>
              </button>

              {/* User */}
              <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center">
                <span className="text-sm font-semibold text-white">RA</span>
              </div>
            </div>
          </div>
        </header>

        {/* Dashboard Content */}
        <div className="p-6">
          {/* Stats Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            {stats.map((stat, index) => {
              const Icon = stat.icon;
              const TrendIcon = stat.trend === 'up' ? ArrowUpRight : ArrowDownRight;
              return (
                <div 
                  key={index}
                  className="bg-[#0f172a] rounded-2xl p-6 border border-white/5 hover:border-blue-500/20 transition-all group"
                >
                  <div className="flex items-start justify-between mb-4">
                    <div className={`p-3 rounded-xl ${
                      stat.color === 'blue' ? 'bg-blue-500/10 text-blue-400' :
                      stat.color === 'green' ? 'bg-green-500/10 text-green-400' :
                      stat.color === 'purple' ? 'bg-purple-500/10 text-purple-400' :
                      'bg-orange-500/10 text-orange-400'
                    }`}>
                      <Icon className="w-5 h-5" />
                    </div>
                    <div className={`flex items-center gap-1 text-xs font-medium ${
                      stat.trend === 'up' ? 'text-green-400' : 'text-red-400'
                    }`}>
                      <TrendIcon className="w-3 h-3" />
                      {stat.change}
                    </div>
                  </div>
                  <h3 className="text-2xl font-bold text-white mb-1">{stat.value}</h3>
                  <p className="text-sm text-gray-400">{stat.title}</p>
                </div>
              );
            })}
          </div>

          {/* Main Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Recent Projects */}
            <div className="lg:col-span-2 bg-[#0f172a] rounded-2xl border border-white/5">
              <div className="p-6 border-b border-white/5 flex items-center justify-between">
                <h3 className="text-lg font-semibold text-white">Recent Projects</h3>
                <button className="p-2 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-colors">
                  <MoreHorizontal className="w-5 h-5" />
                </button>
              </div>
              <div className="p-6 space-y-4">
                {recentProjects.map((project, index) => (
                  <div 
                    key={index}
                    className="flex items-center gap-4 p-4 rounded-xl bg-white/5 hover:bg-white/10 transition-colors group"
                  >
                    <div className="flex-1">
                      <h4 className="font-medium text-white mb-1">{project.name}</h4>
                      <p className="text-sm text-gray-400">{project.client}</p>
                    </div>
                    <div className="text-right">
                      <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${
                        project.status === 'Completed' ? 'bg-green-500/10 text-green-400' :
                        project.status === 'In Progress' ? 'bg-blue-500/10 text-blue-400' :
                        'bg-yellow-500/10 text-yellow-400'
                      }`}>
                        {project.status}
                      </span>
                      <p className="text-xs text-gray-500 mt-1">Due {project.deadline}</p>
                    </div>
                    {/* Progress Bar */}
                    <div className="w-24">
                      <div className="h-2 bg-white/10 rounded-full overflow-hidden">
                        <div 
                          className="h-full bg-blue-500 rounded-full transition-all"
                          style={{ width: `${project.progress}%` }}
                        ></div>
                      </div>
                      <p className="text-xs text-gray-500 mt-1 text-right">{project.progress}%</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Recent Activity */}
            <div className="bg-[#0f172a] rounded-2xl border border-white/5">
              <div className="p-6 border-b border-white/5">
                <h3 className="text-lg font-semibold text-white">Recent Activity</h3>
              </div>
              <div className="p-6 space-y-4">
                {recentActivity.map((activity, index) => {
                  const Icon = activity.icon;
                  return (
                    <div key={index} className="flex items-start gap-3">
                      <div className="p-2 rounded-lg bg-blue-500/10 text-blue-400">
                        <Icon className="w-4 h-4" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm text-white font-medium">{activity.action}</p>
                        <p className="text-xs text-gray-400 truncate">{activity.project}</p>
                        <p className="text-xs text-gray-500 mt-1">{activity.time}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Quick Actions */}
          <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <button className="p-4 rounded-xl bg-blue-600/10 border border-blue-500/20 text-blue-400 hover:bg-blue-600 hover:text-white transition-all text-left">
              <Calendar className="w-6 h-6 mb-2" />
              <span className="font-medium">Schedule Meeting</span>
            </button>
            <button className="p-4 rounded-xl bg-green-600/10 border border-green-500/20 text-green-400 hover:bg-green-600 hover:text-white transition-all text-left">
              <FolderKanban className="w-6 h-6 mb-2" />
              <span className="font-medium">New Project</span>
            </button>
            <button className="p-4 rounded-xl bg-purple-600/10 border border-purple-500/20 text-purple-400 hover:bg-purple-600 hover:text-white transition-all text-left">
              <Users className="w-6 h-6 mb-2" />
              <span className="font-medium">Add Client</span>
            </button>
            <button className="p-4 rounded-xl bg-orange-600/10 border border-orange-500/20 text-orange-400 hover:bg-orange-600 hover:text-white transition-all text-left">
              <TrendingUp className="w-6 h-6 mb-2" />
              <span className="font-medium">View Reports</span>
            </button>
          </div>
        </div>
      </main>
    </div>
  );
};

export default Dashboard;
